import type { BackFlag, ExerciseKind, MuscleWeights } from "./types";
import type { FormGuide } from "./form";

/**
 * Fine Shyte 3 ranked backups (Nov 4, 2026). Randy asked for 4 backups per move, each with a match % for how close it is
 * to the plan move (same muscles, movement pattern, load and feel), and picked brand-new moves only (no Fine Shyte 2 moves).
 * Rules: Planet Fitness gear only (kettlebells + landmine yes; no machine pullover, machine lateral, belt squat, sled,
 * machine high row, Nordic anchor or EZ bar), no bar on the spine, no loaded crunches, no shrugs, left shoulder and L4 notes on every move.
 * The match % is an editorial judgement written for this app, not a measurement.
 */

